(function(){
  const V67_KEYS={pettyCash:'imode_v67_petty_cash',spareParts:'imode_v67_spare_parts',purchaseOrders:'imode_v67_purchase_orders'};
  let pettyCashEntries=JSON.parse(localStorage.getItem(V67_KEYS.pettyCash)||'[]');
  let sparePartsStock=JSON.parse(localStorage.getItem(V67_KEYS.spareParts)||'[]');
  let purchaseOrders=JSON.parse(localStorage.getItem(V67_KEYS.purchaseOrders)||'[]');
  let pettyPendingReceipts=[], qcPendingMediaLocal=[];

  PAGE_INFO.th['petty-cash']=['เงินสดย่อยแผนก Service','เบิกซื้อของภายในแผนก บันทึกค่าใช้จ่าย พร้อมสรุปรายเดือนเพื่อเคลียร์บัญชี'];
  PAGE_INFO.en['petty-cash']=['Service Petty Cash','Department purchases, expense records and monthly clearing summary'];
  PAGE_INFO.th['spare-parts']=['สต๊อกอะไหล่และการสั่งซื้อ','ระบุว่าแต่ละเครื่องใช้อะไหล่อะไร ตั้งค่าจำนวนต่ำสุด/สูงสุด และแจ้งเตือนล่วงหน้าเมื่อใกล้ต้องสั่งซื้อ'];
  PAGE_INFO.en['spare-parts']=['Spare Parts & Purchasing','Which parts each machine uses, min/max levels and early reorder alerts'];

  function ensureInternalCustomer(){ let cu=customers.find(c=>String(c.name||'').trim()==='บริษัท ไอโมด พลัส จำกัด'); if(!cu){ cu={id:'CUST-INTERNAL-IMODE',name:'บริษัท ไอโมด พลัส จำกัด',branch:'สำนักงานใหญ่',contact:'แผนก Service',phone:settings.companyPhone||'',email:settings.companyEmail||'',location:'ภายในบริษัท',address:settings.companyAddress||'',note:'ลูกค้าภายในสำหรับ QC / เบิกภายใน / งานคลังอะไหล่'}; customers.unshift(cu);} return cu.id; }
  ensureInternalCustomer();

  function saveLocal(){ localStorage.setItem(K.cases,JSON.stringify(cases)); localStorage.setItem(K.tech,JSON.stringify(technicians)); localStorage.setItem(K.customers,JSON.stringify(customers)); localStorage.setItem(K.machines,JSON.stringify(machines)); localStorage.setItem(K.notifications,JSON.stringify(notifications)); localStorage.setItem(K.quotes,JSON.stringify(quotations)); localStorage.setItem(K.settings,JSON.stringify(settings)); localStorage.setItem(K.user,JSON.stringify(currentUser)); localStorage.setItem(K.warranties,JSON.stringify(warranties)); localStorage.setItem(K.documents,JSON.stringify(machineDocuments)); localStorage.setItem(K.lineRequests,JSON.stringify(lineRequests)); localStorage.setItem(K.serviceReports,JSON.stringify(serviceReports)); localStorage.setItem(K.qcRecords,JSON.stringify(qcRecords)); localStorage.setItem(V67_KEYS.pettyCash,JSON.stringify(pettyCashEntries)); localStorage.setItem(V67_KEYS.spareParts,JSON.stringify(sparePartsStock)); localStorage.setItem(V67_KEYS.purchaseOrders,JSON.stringify(purchaseOrders)); }
  window.saveLocal=saveLocal;

  function currentMonthValue(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
  function monthKeyOf(dateStr=''){return String(dateStr||'').slice(0,7)}
  function money2(n){return money(Number(n)||0)}
  function statusThai(s=''){return ({Pending:'รอตรวจ',Draft:'รอตรวจ','In Progress':'กำลังตรวจ',Pass:'ผ่าน',Conditional:'ผ่านแบบมีเงื่อนไข',Fail:'ไม่ผ่าน','N/A':'N/A'})[s]||s}
  function qcTypeThai(s=''){return ({'Incoming Inspection':'ตรวจรับเข้า','Pre-Delivery QC':'ตรวจก่อนส่งมอบ','Post-Service QC':'ตรวจหลังซ่อม','Installation Acceptance':'ตรวจรับหลังติดตั้ง','PM Verification':'ตรวจยืนยัน PM'})[s]||s}
  function fileDateText(x){try{return new Date(x).toLocaleDateString('th-TH')}catch(e){return '-'}}
  async function filesToObjects(fileList,maxCount=4,maxMb=3){ const out=[]; for(const file of [...(fileList||[])]){ if(out.length>=maxCount)break; if(file.size>maxMb*1024*1024){toastMsg(`ไฟล์ ${file.name} ใหญ่เกิน ${maxMb} MB`);continue} const data=await new Promise((res,rej)=>{const r=new FileReader(); r.onload=()=>res(r.result); r.onerror=rej; r.readAsDataURL(file)}); out.push({name:file.name,type:file.type,size:file.size,data:String(data),createdAt:new Date().toISOString()}); } return out; }

  function qcStatusFilterNormalized(s='all'){ if(s==='Fail') return ['Fail','Conditional']; return [s]; }
  window.setQcStatusFilter=function(s='all'){ if(typeof qcStatusFilter!=='undefined') qcStatusFilter.value=s; renderQc(); };
  window.renderQc=function(){ if(typeof qcTable==='undefined')return; const q=(qcSearch?.value||'').toLowerCase(),tf=qcTypeFilter?.value||'all',sf=qcStatusFilter?.value||'all'; qcKpiAll.textContent=qcRecords.length; qcKpiDraft.textContent=qcRecords.filter(x=>x.status==='Draft').length; qcKpiProgress.textContent=qcRecords.filter(x=>x.status==='In Progress').length; qcKpiPass.textContent=qcRecords.filter(x=>x.status==='Pass').length; qcKpiFail.textContent=qcRecords.filter(x=>['Fail','Conditional'].includes(x.status)).length; const qcFiltered=[...qcRecords].filter(x=>{const m=machineById(x.machineId),cu=customerById(x.customerId); const bag=[x.qcNo,qcTypeThai(x.type),x.type,x.inspector,x.targetCompany,cu?.name,machinePrimaryName(m),m?.model,m?.serial].join(' ').toLowerCase(); return (!q||bag.includes(q))&&(tf==='all'||x.type===tf)&&(sf==='all'||qcStatusFilterNormalized(sf).includes(x.status));}).sort((a,b)=>new Date(b.qcDate||b.updatedAt)-new Date(a.qcDate||a.updatedAt)); const qcInfo=paginateList('qc',qcFiltered,[q,tf,sf].join('|')),list=qcInfo.list; qcTable.innerHTML=list.length?list.map(x=>{const m=machineById(x.machineId),cu=customerById(x.customerId),st=qcChecklistStats(x); return `<tr><td><b>${esc(x.qcNo)}</b>${x.isDemo?'<span class="subtext">TEST DATA</span>':''}</td><td>${x.qcDate?new Date(x.qcDate+'T00:00:00').toLocaleDateString(uiLocale()):'-'}</td><td>${esc(qcTypeThai(x.type))}</td><td>${esc(cu?.name||'-')}${x.targetCompany?`<span class="subtext">ส่งให้: ${esc(x.targetCompany)}</span>`:''}</td><td>${esc(machinePrimaryName(m)||'-')}<span class="subtext">${esc(m?.model||'-')} · S/N ${esc(m?.serial||'-')}</span></td><td>${esc(x.inspector||'-')}</td><td><span class="qc-result-badge ${qcStatusClass(x.status)}">${esc(statusThai(x.status)||'รอตรวจ')}</span></td><td><div class="qc-check-progress"><small>${st.done}/${st.total}</small><div class="qc-meter"><i style="width:${st.pct}%"></i></div></div></td><td><button class="mini-btn" onclick="previewQc(${imodeJsArg(x.id)})">ดู / พิมพ์</button> <button class="mini-btn" onclick="openQcModal(${imodeJsArg(x.id)})">แก้ไข</button></td></tr>`}).join(''):`<tr><td colspan="9"><div class="empty">ยังไม่มีรายการ QC เครื่อง</div></td></tr>`; qcCards.innerHTML=list.map(x=>{const m=machineById(x.machineId),cu=customerById(x.customerId),st=qcChecklistStats(x); return `<div class="mobile-data-card"><div class="card-top"><div><h4>${esc(x.qcNo)}</h4><p>${esc(cu?.name||'-')}</p></div><span class="qc-result-badge ${qcStatusClass(x.status)}">${esc(statusThai(x.status))}</span></div><p><b>${esc(machinePrimaryName(m)||'-')}</b><br>${esc(m?.model||'-')} · S/N ${esc(m?.serial||'-')}</p><p>${esc(qcTypeThai(x.type)||'-')} · Checklist ${st.done}/${st.total}</p><div class="card-actions"><button class="soft-btn" onclick="previewQc(${imodeJsArg(x.id)})">ดู / พิมพ์</button><button class="primary-btn" onclick="openQcModal(${imodeJsArg(x.id)})">แก้ไข</button></div></div>`}).join(''); if(typeof renderListPager==='function')renderListPager('qc',qcInfo,qcRecords.length); }
  window.setQcItemResult=function(i,val){ if(!qcDraftChecklist[i])return; qcDraftChecklist[i].result=val; renderQcChecklist(); }
  window.renderQcChecklist=function(){ if(typeof qcChecklistBox==='undefined')return; qcChecklistBox.innerHTML=qcDraftChecklist.map((it,i)=>`<div class="qc-check-row v67"><div class="qc-check-no">${i+1}</div><div class="qc-check-name"><b>${esc(it.labelTh)}</b><small>${esc(it.labelEn)}</small></div><div class="qc-status-pills"><button type="button" class="qc-status-pill pending ${it.result==='Pending'?'active':''}" onclick="setQcItemResult(${i},'Pending')">รอตรวจ</button><button type="button" class="qc-status-pill pass ${it.result==='Pass'?'active':''}" onclick="setQcItemResult(${i},'Pass')">ผ่าน</button><button type="button" class="qc-status-pill fail ${it.result==='Fail'?'active':''}" onclick="setQcItemResult(${i},'Fail')">ไม่ผ่าน</button><button type="button" class="qc-status-pill na ${it.result==='N/A'?'active':''}" onclick="setQcItemResult(${i},'N/A')">N/A</button></div><input class="qc-remark" placeholder="หมายเหตุ / ค่าที่วัด / สิ่งที่พบ" value="${esc(it.remark||'')}" oninput="qcDraftChecklist[${i}].remark=this.value"></div>`).join(''); updateQcSummary(); }
  window.updateQcSummary=function(){ if(typeof qcSummary==='undefined')return; const st=qcChecklistStats({checklist:qcDraftChecklist}); qcSummary.innerHTML=`<div><small>ตรวจแล้ว</small><b>${st.done}/${st.total}</b></div><div><small>PASS</small><b>${st.pass}</b></div><div><small>FAIL</small><b>${st.fail}</b></div>`; }
  window.qcCustomerChanged=function(selectedMachine=''){ const cid=qcCustomer.value; const list=machines.filter(m=>!cid||m.customerId===cid); qcMachine.innerHTML='<option value="">เลือกเครื่อง</option>'+list.map(m=>`<option value="${esc(String(m.id))}">${esc(machinePrimaryName(m))} · ${esc(m.model||'-')} · S/N ${esc(m.serial||'-')}</option>`).join(''); if(selectedMachine&&list.some(m=>m.id===selectedMachine)) qcMachine.value=selectedMachine; if(typeof qcCase!=='undefined') qcCase.innerHTML=qcCaseOptions(qcCustomer.value,qcMachine.value,''); }
  window.qcCaseOptions=function(cid='',mid='',selected=''){ const list=cases.filter(c=>(!cid||c.customerId===cid)&&(!mid||c.machineId===mid)); return '<option value="">ไม่ผูก Service Case</option>'+list.map(c=>`<option value="${esc(String(c.id))}" ${selected===c.id?'selected':''}>${esc(c.ticket)} · ${esc(c.status||'')}</option>`).join(''); }
  window.qcMediaChanged=async function(input){ const added=await filesToObjects(input.files,8,4); qcPendingMediaLocal=(qcPendingMediaLocal||[]).concat(added).slice(0,8); input.value=''; renderQcMedia(); }
  window.removeQcMedia=function(i){ qcPendingMediaLocal.splice(i,1); renderQcMedia(); }
  window.renderQcMedia=function(){ const box=document.getElementById('qcMediaPreview'); if(!box)return; box.innerHTML=(qcPendingMediaLocal||[]).map((f,i)=>`<div class="qc-media-item">${String(f.type||'').startsWith('video/')?`<video src="${esc(String(f.data))}" controls></video>`:`<img src="${esc(String(f.data))}" alt="qc media">`}<div class="meta"><small>${esc(f.name||('ไฟล์ '+(i+1)))}</small><button type="button" class="mini-btn" onclick="removeQcMedia(${i})">ลบ</button></div></div>`).join('') || '<div class="qc-hint">ยังไม่มีรูปภาพหรือวิดีโอประกอบ QC</div>'; }
  window.openQcModal=function(id='',presetMachine=''){ if(!requirePermission('qc.edit'))return; const old=qcRecord(id)||{},m0=machineById(old.machineId||presetMachine),internalId=ensureInternalCustomer(),cid=old.customerId||m0?.customerId||internalId; qcEditingId=old.id||''; qcPendingMediaLocal=JSON.parse(JSON.stringify(old.media||[])); qcDraftChecklist=(old.checklist?.length?old.checklist:QC_CHECKLIST_MASTER.map(x=>({id:x.id,labelTh:x.th,labelEn:x.en,result:'Pending',remark:''}))).map(x=>({...x})); openModal(old.id?'แก้ไข QC เครื่อง':'สร้าง QC เครื่อง','เชื่อม Customer / Machine / Service Case พร้อม Checklist, รูปภาพ และวิดีโอประกอบ QC',`<form id="qcForm"><div class="qc-form-grid"><div class="field"><label>QC เลขที่</label><input id="qcNoInput" value="${esc(old.qcNo||qcNo())}" readonly></div><div class="field"><label>ประเภท QC *</label><select id="qcType">${['Incoming Inspection','Pre-Delivery QC','Post-Service QC','Installation Acceptance','PM Verification'].map(x=>`<option ${old.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>วันที่ตรวจ *</label><input id="qcDate" type="date" value="${esc(old.qcDate||todayISO())}" required></div><div class="field"><label>ลูกค้า *</label><select id="qcCustomer" onchange="qcCustomerChanged()"><option value="">เลือกลูกค้า</option>${customers.map(c=>`<option value="${esc(String(c.id))}" ${cid===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>เครื่องจักร *</label><select id="qcMachine" onchange="qcCase.innerHTML=qcCaseOptions(qcCustomer.value,this.value,'')"></select></div><div class="field"><label>Service Case</label><select id="qcCase"></select></div><div class="field"><label>ผู้ตรวจ QC *</label><input id="qcInspector" value="${esc(old.inspector||currentUser?.name||'')}" required></div><div class="field"><label>ผู้อนุมัติ / Reviewer</label><input id="qcReviewer" value="${esc(old.reviewer||'')}"></div><div class="field"><label>สถานะ / ผล QC</label><select id="qcStatus"><option value="Draft" ${old.status==='Draft'?'selected':''}>ร่าง / รอตรวจ</option><option value="In Progress" ${old.status==='In Progress'?'selected':''}>กำลังตรวจ</option><option value="Pass" ${old.status==='Pass'?'selected':''}>ผ่าน</option><option value="Conditional" ${old.status==='Conditional'?'selected':''}>ผ่านแบบมีเงื่อนไข</option><option value="Fail" ${old.status==='Fail'?'selected':''}>ไม่ผ่าน</option></select></div><div class="field"><label>QC เพื่อส่งให้บริษัท</label><input id="qcTargetCompany" placeholder="เช่น บริษัท ไอโมด พลัส จำกัด" value="${esc(old.targetCompany||'บริษัท ไอโมด พลัส จำกัด')}"></div><div class="field full"><label>Checklist QC</label><div id="qcSummary" class="qc-summary-box"></div><div id="qcChecklistBox" class="qc-checklist"></div></div><div class="field full"><label>สิ่งที่พบ / Findings</label><textarea id="qcFindings">${esc(old.findings||'')}</textarea></div><div class="field full"><label>รูปภาพและวิดีโอประกอบ QC</label><div class="qc-media-box"><div class="qc-media-tools"><label class="soft-btn" style="cursor:pointer">📷 เพิ่มรูปภาพ<input type="file" accept="image/*" multiple style="display:none" onchange="qcMediaChanged(this)"></label><label class="soft-btn" style="cursor:pointer">🎥 เพิ่มวิดีโอ<input type="file" accept="video/*" multiple style="display:none" onchange="qcMediaChanged(this)"></label><span class="qc-hint">แนบรวมได้สูงสุด 8 ไฟล์</span></div><div id="qcMediaPreview" class="qc-media-preview"></div></div></div><div class="field full"><label>Corrective Action / การแก้ไข</label><textarea id="qcCorrective">${esc(old.correctiveAction||'')}</textarea></div><div class="field full"><label>หมายเหตุ / Release Note</label><textarea id="qcNote">${esc(old.note||'')}</textarea></div></div><div class="button-row"><button type="button" class="soft-btn" onclick="closeModal()">ยกเลิก</button><button type="button" class="soft-btn" onclick="previewQcDraft()">🧾 ดูใบ QC</button><button class="primary-btn action-3d-orange">💾 บันทึก QC</button></div></form>`,true); modalPanel.classList.add('large'); setTimeout(()=>{qcCustomerChanged(old.machineId||presetMachine); qcCase.innerHTML=qcCaseOptions(cid,old.machineId||presetMachine,old.caseId||''); renderQcChecklist(); renderQcMedia(); qcForm.onsubmit=e=>{e.preventDefault(); saveQc()};},20); }
  window.qcDraftRecord=function(){ const m=machineById(qcMachine?.value),cu=customerById(qcCustomer?.value); return {id:qcEditingId||'DRAFT',qcNo:qcNoInput?.value||'DRAFT',type:qcType?.value||'Pre-Delivery QC',qcDate:qcDate?.value||todayISO(),customerId:cu?.id||'',machineId:m?.id||'',caseId:qcCase?.value||'',inspector:qcInspector?.value?.trim()||'',reviewer:qcReviewer?.value?.trim()||'',status:qcStatus?.value||'Draft',targetCompany:qcTargetCompany?.value?.trim()||'',checklist:JSON.parse(JSON.stringify(qcDraftChecklist)),findings:qcFindings?.value?.trim()||'',correctiveAction:qcCorrective?.value?.trim()||'',note:qcNote?.value?.trim()||'',media:JSON.parse(JSON.stringify(qcPendingMediaLocal||[])),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}; }
  window.saveQc=function(){ const rec=qcDraftRecord(); if(!rec.customerId||!rec.machineId){toastMsg('กรุณาเลือกลูกค้าและเครื่องจักร');return} const old=qcRecord(qcEditingId); rec.id=old?.id||uid(); rec.createdAt=old?.createdAt||new Date().toISOString(); if(old)qcRecords=qcRecords.map(x=>x.id===rec.id?rec:x); else qcRecords.unshift(rec); saveLocal(); closeModal(); renderAll(); toastMsg('บันทึก '+rec.qcNo+' แล้ว'); }
  window.qcDocHTML=function(q){ const m=machineById(q.machineId)||{},cu=customerById(q.customerId)||{},c=cases.find(x=>x.id===q.caseId),st=qcChecklistStats(q),pics=(q.media||[]).filter(x=>String(x.type||'').startsWith('image/')).slice(0,4); const rows=(q.checklist||[]).map((it,i)=>`<tr><td>${i+1}</td><td class="wrap">${esc(it.labelTh||it.labelEn||it.id)}</td><td>${esc(statusThai(it.result)||it.result||'-')}</td><td class="wrap">${esc(it.remark||'-')}</td></tr>`).join(''); return `<div class="qc-a4" id="qcPrintDoc"><div class="qc-a4-head"><div><img src="${esc(String(IMODE_LOGO))}" alt="I-MODE"></div><div><h1>รายงานตรวจสอบคุณภาพเครื่องจักร (QC)</h1><div class="qc-a4-meta"><b>${esc(settings.companyNameTh||settings.companyName||'บริษัท ไอโมด พลัส จำกัด')}</b><br>${esc(settings.companyAddress||'')}<br>โทร. ${esc(settings.companyPhone||'-')} · ${esc(settings.companyEmail||'-')}</div></div></div><div class="qc-a4-info"><div><b>เลขที่ QC:</b> ${esc(q.qcNo)}<br><b>ประเภท QC:</b> ${esc(qcTypeThai(q.type))}<br><b>วันที่ตรวจ:</b> ${esc(q.qcDate||'-')}<br><b>Service Case:</b> ${esc(c?.ticket||'-')}</div><div><b>ลูกค้า:</b> ${esc(cu.name||'-')}<br><b>QC เพื่อส่งให้:</b> ${esc(q.targetCompany||'บริษัท ไอโมด พลัส จำกัด')}<br><b>เครื่องจักร:</b> ${esc(machinePrimaryName(m)||'-')}<br><b>Model / Serial:</b> ${esc(m.model||'-')} / ${esc(m.serial||'-')}</div></div><table><thead><tr><th>ลำดับ</th><th>รายการตรวจสอบ</th><th>ผล</th><th>หมายเหตุ</th></tr></thead><tbody>${rows}</tbody></table><div class="qc-a4-note"><b>สิ่งที่พบ:</b> ${esc(q.findings||'-')}<br><b>การแก้ไข:</b> ${esc(q.correctiveAction||'-')}<br><b>หมายเหตุ / Release Note:</b> ${esc(q.note||'-')}</div>${pics.length?`<div class="qc-doc-section-title">รูปภาพประกอบ QC</div><div class="qc-a4-media">${pics.map(x=>`<img src="${esc(String(x.data))}" alt="QC media">`).join('')}</div>`:''}<div class="qc-a4-info"><div><b>สรุปผลสุดท้าย:</b> ${esc(statusThai(q.status)||q.status||'รอตรวจ')}<br><b>Checklist:</b> ${st.done}/${st.total} · PASS ${st.pass} · FAIL ${st.fail}</div><div><b>ผู้ตรวจ:</b> ${esc(q.inspector||'-')}<br><b>ผู้อนุมัติ:</b> ${esc(q.reviewer||'-')}</div></div><div class="qc-a4-sign"><div><b>ผู้ตรวจ QC</b><div>วันที่ ....................</div></div><div><b>Service / Technical</b><div>วันที่ ....................</div></div><div><b>ผู้อนุมัติ / ผู้รับมอบ</b><div>วันที่ ....................</div></div></div></div>`; }
  window.openQcPreviewRecord=function(q,draft=false){ openModal(draft?'ตัวอย่างใบ QC':'QC '+q.qcNo,draft?'Preview ก่อนบันทึก':`${qcTypeThai(q.type)} · ${statusThai(q.status)}`,qcDocHTML(q)+`<div class="button-row" style="margin-top:12px"><button class="soft-btn" onclick="closeModal()">ปิด</button><button class="soft-btn" onclick="printQcCurrent()">🖨 พิมพ์ / PDF</button>${!draft?`<button class="primary-btn" onclick="openQcModal(${imodeJsArg(q.id)})">แก้ไข</button>`:''}</div>`,true); modalPanel.classList.add('large'); }
  window.previewQc=function(id){ const q=qcRecord(id); if(q)openQcPreviewRecord(q,false) }
  window.previewQcDraft=function(){ openQcPreviewRecord(qcDraftRecord(),true) }
  window.printQcCurrent=function(){ const doc=document.getElementById('qcPrintDoc'); if(!doc)return; const css=(document.getElementById('qcV66Style')?.textContent||'')+(document.getElementById('v67EnhanceStyle')?.textContent||''); const w=window.open('','_blank','width=1200,height=900'); w.document.write(`<!doctype html><html lang="th"><head><meta charset="utf-8"><title>Machine QC</title><style>${css}</style></head><body style="background:#f6f8fc;padding:12px">${doc.outerHTML}<script>window.onload=()=>window.print()<\/script></body></html>`); w.document.close(); }
  window.exportQcCSV=function(){ if(!qcRecords.length){toastMsg('ยังไม่มีข้อมูล QC');return} const rows=[['QC No','Date','Type TH','Customer','Target Company','Machine','Model','Serial','Inspector','Reviewer','Status TH','Checklist Done','Checklist Total','Findings','Corrective Action','Note','Media Count'],...qcRecords.map(q=>{const m=machineById(q.machineId),cu=customerById(q.customerId),st=qcChecklistStats(q); return [q.qcNo,q.qcDate,qcTypeThai(q.type),cu?.name||'',q.targetCompany||'',machinePrimaryName(m)||'',m?.model||'',m?.serial||'',q.inspector||'',q.reviewer||'',statusThai(q.status),st.done,st.total,q.findings||'',q.correctiveAction||'',q.note||'',(q.media||[]).length]})]; const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n'); downloadTextFile(`I-MODE_QC_${todayISO()}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8'); }

  function pettyNo(){ const ym=currentMonthValue().replace('-',''); let max=0; pettyCashEntries.forEach(x=>{const m=String(x.docNo||'').match(/PC-\d{6}-(\d+)/); if(m)max=Math.max(max,Number(m[1])||0)}); return `PC-${ym}-${String(max+1).padStart(3,'0')}`; }
  function pettyStatusClass(s=''){ return s==='เคลียร์แล้ว'?'petty-cleared':s==='ยกเลิก'?'petty-cancel':'petty-pending'; }
  function pettyFilteredList(){ const q=(pettySearch?.value||'').toLowerCase(),month=pettyMonthFilter?.value||currentMonthValue(),st=pettyStatusFilter?.value||'all'; return pettyCashEntries.filter(x=>(window.imodePeriod?window.imodePeriod.contains('pettyCash',x.date):(!month||monthKeyOf(x.date)===month))&&(!st||st==='all'||x.status===st)&&(!q||[x.docNo,x.requester,x.vendor,x.purpose,x.category].join(' ').toLowerCase().includes(q))).sort((a,b)=>new Date(b.date)-new Date(a.date)); }
  window.renderPettyCash=function(){ if(typeof pettyTable==='undefined')return; if(!pettyMonthFilter.value) pettyMonthFilter.value=currentMonthValue(); /* 2026-09-15: js/66's ปี/เดือน/สัปดาห์ control decides the period (month by default, as before); the totals below follow every filter, not just the month. */ if(window.imodePeriod) window.imodePeriod.mount('pettyCash','pettyPeriodHost','month',function(){renderPettyCash()}); const pettyFiltered=pettyFilteredList(); const pettyInfo=paginateList('pettyCash',pettyFiltered,[pettyMonthFilter.value||'',(document.getElementById('pettySearch')?.value||''),(document.getElementById('pettyStatusFilter')?.value||''),(window.imodePeriod?window.imodePeriod.sig('pettyCash'):'')].join('|')); const list=pettyInfo.list; const allMonth=pettyFiltered; const total=allMonth.reduce((s,x)=>s+(Number(x.amount)||0),0),pending=allMonth.filter(x=>x.status==='รอเคลียร์').length,cleared=allMonth.filter(x=>x.status==='เคลียร์แล้ว').length; pcKpiMonthTotal.textContent=(Number(total)||0).toLocaleString('th-TH'); pcKpiPending.textContent=pending; pcKpiCleared.textContent=cleared; pcKpiCount.textContent=allMonth.length; pettyTable.innerHTML=list.length?list.map(x=>`<tr><td><b>${esc(x.docNo)}</b></td><td>${fileDateText(x.date)}</td><td>${esc(x.requester||'-')}</td><td>${esc(x.category||'-')}</td><td>${esc(x.purpose||'-')}</td><td>${esc(x.vendor||'-')}</td><td>${money2(x.amount)}</td><td><span class="petty-status-badge ${pettyStatusClass(x.status)}">${esc(x.status||'รอเคลียร์')}</span></td><td>${(x.receipts||[]).length?`<span class="info-tag">${(x.receipts||[]).length} ไฟล์</span>`:'-'}</td><td><button class="mini-btn" onclick="openPettyCashPreview(${imodeJsArg(x.id)})">ดู</button> <button class="mini-btn" onclick="openPettyCashModal(${imodeJsArg(x.id)})">แก้ไข</button></td></tr>`).join(''):`<tr><td colspan="10"><div class="empty">ยังไม่มีรายการเงินสดย่อย</div></td></tr>`; pettyCards.innerHTML=list.map(x=>`<div class="mobile-data-card"><div class="card-top"><div><h4>${esc(x.docNo)}</h4><p>${esc(x.requester||'-')}</p></div><span class="petty-status-badge ${pettyStatusClass(x.status)}">${esc(x.status||'รอเคลียร์')}</span></div><p><b>${money2(x.amount)}</b><br>${esc(x.purpose||'-')}</p><p>${fileDateText(x.date)} · ${esc(x.vendor||'-')}</p><div class="card-actions"><button class="soft-btn" onclick="openPettyCashPreview(${imodeJsArg(x.id)})">ดู</button><button class="primary-btn" onclick="openPettyCashModal(${imodeJsArg(x.id)})">แก้ไข</button></div></div>`).join(''); if(typeof renderListPager==='function')renderListPager('pettyCash',pettyInfo,pettyCashEntries.length); }
  window.pettyCashMediaChanged=async function(input){ const added=await filesToObjects(input.files,6,4); pettyPendingReceipts=(pettyPendingReceipts||[]).concat(added).slice(0,6); input.value=''; renderPettyCashReceipts(); }
  window.removePettyReceipt=function(i){ pettyPendingReceipts.splice(i,1); renderPettyCashReceipts(); }
  window.renderPettyCashReceipts=function(){ const box=document.getElementById('pettyReceiptPreview'); if(!box)return; box.innerHTML=(pettyPendingReceipts||[]).map((f,i)=>`<div class="media-thumb">${String(f.type||'').startsWith('video/')?`<video src="${esc(String(f.data))}" controls></video>`:String(f.type||'').includes('pdf')?`<div style="height:90px;display:grid;place-items:center;background:#eef3ff;font-weight:800;color:#35507e">PDF</div>`:`<img src="${esc(String(f.data))}" alt="receipt">`}<div class="meta"><small>${esc(f.name||('receipt '+(i+1)))}</small><button type="button" class="mini-btn" onclick="removePettyReceipt(${i})">ลบ</button></div></div>`).join('')||'<div class="qc-hint">ยังไม่มีหลักฐานแนบ</div>'; }
  function pettyEntryById(id){ return pettyCashEntries.find(x=>x.id===id) }
  window.openPettyCashModal=function(id=''){ const old=pettyEntryById(id)||{}; pettyPendingReceipts=JSON.parse(JSON.stringify(old.receipts||[])); openModal(old.id?'แก้ไขเงินสดย่อย':'เบิก/บันทึกเงินสดย่อย','ใช้บันทึกการเบิกเงินสดย่อย ซื้อของภายในแผนก และเคลียร์บัญชีรายเดือน',`<form id="pettyForm"><div class="form-grid cols2"><div class="field"><label>เลขที่เอกสาร</label><input id="pcDocNo" value="${esc(old.docNo||pettyNo())}" readonly></div><div class="field"><label>วันที่ *</label><input id="pcDate" type="date" value="${esc(old.date||todayISO())}" required></div><div class="field"><label>ผู้เบิก *</label><input id="pcRequester" value="${esc(old.requester||currentUser?.name||'')}" required></div><div class="field"><label>หมวดค่าใช้จ่าย</label><select id="pcCategory"><option ${old.category==='อะไหล่'?'selected':''}>อะไหล่</option><option ${old.category==='วัสดุสิ้นเปลือง'?'selected':''}>วัสดุสิ้นเปลือง</option><option ${old.category==='อุปกรณ์ช่าง'?'selected':''}>อุปกรณ์ช่าง</option><option ${old.category==='ขนส่ง/จัดส่ง'?'selected':''}>ขนส่ง/จัดส่ง</option><option ${old.category==='อื่นๆ' || !old.category ? 'selected' : ''}>อื่นๆ</option></select></div><div class="field full"><label>วัตถุประสงค์ *</label><textarea id="pcPurpose" required>${esc(old.purpose||'')}</textarea></div><div class="field"><label>ร้านค้า / ผู้ขาย</label><input id="pcVendor" value="${esc(old.vendor||'')}"></div><div class="field"><label>จำนวนเงิน (บาท) *</label><input id="pcAmount" type="number" min="0" step="0.01" value="${Number(old.amount)||''}" required></div><div class="field"><label>สถานะ</label><select id="pcStatus"><option ${old.status==='รอเคลียร์' || !old.status ? 'selected' : ''}>รอเคลียร์</option><option ${old.status==='เคลียร์แล้ว'?'selected':''}>เคลียร์แล้ว</option><option ${old.status==='ยกเลิก'?'selected':''}>ยกเลิก</option></select></div><div class="field"><label>อ้างอิง / ใบเสร็จ</label><input id="pcReference" value="${esc(old.reference||'')}"></div><div class="field full"><label>หมายเหตุ</label><textarea id="pcNote">${esc(old.note||'')}</textarea></div><div class="field full"><label>แนบหลักฐาน (รูป / วิดีโอ / ใบเสร็จ)</label><div class="qc-media-box"><div class="qc-media-tools"><label class="soft-btn" style="cursor:pointer">📎 เพิ่มไฟล์<input type="file" accept="image/*,video/*,application/pdf" multiple style="display:none" onchange="pettyCashMediaChanged(this)"></label><span class="qc-hint">แนบได้สูงสุด 6 ไฟล์</span></div><div id="pettyReceiptPreview" class="media-thumb-grid"></div></div></div></div><div class="button-row"><button type="button" class="soft-btn" onclick="closeModal()">ยกเลิก</button><button class="primary-btn action-3d-orange">💾 บันทึกรายการ</button></div></form>`,true); modalPanel.classList.add('large'); setTimeout(()=>{renderPettyCashReceipts(); pettyForm.onsubmit=e=>{e.preventDefault(); savePettyCash(id)};},20); }
  window.savePettyCash=function(id=''){ const old=pettyEntryById(id)||{}; const obj={id:old.id||uid(),docNo:pcDocNo.value,date:pcDate.value,requester:pcRequester.value.trim(),category:pcCategory.value,purpose:pcPurpose.value.trim(),vendor:pcVendor.value.trim(),amount:Number(pcAmount.value)||0,status:pcStatus.value,reference:pcReference.value.trim(),note:pcNote.value.trim(),receipts:JSON.parse(JSON.stringify(pettyPendingReceipts||[])),createdAt:old.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()}; if(!obj.requester||!obj.purpose||!obj.amount){toastMsg('กรุณากรอกข้อมูลให้ครบ');return} if(old.id) pettyCashEntries=pettyCashEntries.map(x=>x.id===obj.id?obj:x); else pettyCashEntries.unshift(obj); saveLocal(); closeModal(); renderAll(); toastMsg('บันทึกรายการเงินสดย่อยแล้ว'); }
  window.openPettyCashPreview=function(id){ const x=pettyEntryById(id); if(!x)return; openModal('รายละเอียดเงินสดย่อย',`${x.docNo} · ${x.requester}`,`<div class="detail-grid"><div class="detail-box"><small>วันที่</small><b>${fileDateText(x.date)}</b></div><div class="detail-box"><small>จำนวนเงิน</small><b>${money2(x.amount)}</b></div><div class="detail-box"><small>หมวดค่าใช้จ่าย</small><b>${esc(x.category||'-')}</b></div><div class="detail-box"><small>สถานะ</small><b><span class="petty-status-badge ${pettyStatusClass(x.status)}">${esc(x.status||'-')}</span></b></div><div class="detail-box full"><small>วัตถุประสงค์</small><b>${esc(x.purpose||'-')}</b></div><div class="detail-box"><small>ร้านค้า / ผู้ขาย</small><b>${esc(x.vendor||'-')}</b></div><div class="detail-box"><small>อ้างอิง</small><b>${esc(x.reference||'-')}</b></div><div class="detail-box full"><small>หมายเหตุ</small><b>${esc(x.note||'-')}</b></div></div>${(x.receipts||[]).length?`<div class="section-title" style="margin-top:12px">หลักฐานแนบ</div><div class="media-thumb-grid">${(x.receipts||[]).map(f=>`<div class="media-thumb">${String(f.type||'').startsWith('video/')?`<video src="${esc(String(f.data))}" controls></video>`:String(f.type||'').includes('pdf')?`<div style="height:90px;display:grid;place-items:center;background:#eef3ff;font-weight:800;color:#35507e">PDF</div>`:`<img src="${esc(String(f.data))}" alt="receipt">`}<div class="meta"><small>${esc(f.name||'file')}</small></div></div>`).join('')}</div>`:''}<div class="button-row" style="margin-top:12px"><button class="soft-btn" onclick="closeModal()">ปิด</button><button class="primary-btn" onclick="openPettyCashModal(${imodeJsArg(x.id)})">แก้ไข</button></div>`,true); modalPanel.classList.add('large'); }
  window.exportPettyCashCSV=function(){ const month=pettyMonthFilter?.value||currentMonthValue(); const list=pettyCashEntries.filter(x=>monthKeyOf(x.date)===month); if(!list.length){toastMsg('ยังไม่มีข้อมูลเงินสดย่อยในเดือนนี้');return} const rows=[['Doc No','Date','Requester','Category','Purpose','Vendor','Amount','Status','Reference','Note'],...list.map(x=>[x.docNo,x.date,x.requester,x.category,x.purpose,x.vendor,x.amount,x.status,x.reference||'',x.note||''])]; const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n'); downloadTextFile(`I-MODE_Petty_Cash_${month}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8'); }
  window.previewPettyCashMonthly=function(){ const month=pettyMonthFilter?.value||currentMonthValue(); const list=pettyCashEntries.filter(x=>monthKeyOf(x.date)===month); const total=list.reduce((s,x)=>s+(Number(x.amount)||0),0); const catMap={}; list.forEach(x=>catMap[x.category||'อื่นๆ']=(catMap[x.category||'อื่นๆ']||0)+(Number(x.amount)||0)); openModal('สรุปเงินสดย่อยรายเดือน',`เดือน ${month}`,`<div class="backup-grid"><div class="summary-inline-card"><h4>ยอดรวมทั้งเดือน</h4><div class="summary-number">${money2(total)}</div><p>รวม ${list.length} รายการ</p></div><div class="summary-inline-card"><h4>สถานะการเคลียร์</h4><div class="info-tag-row"><span class="info-tag">รอเคลียร์ ${list.filter(x=>x.status==='รอเคลียร์').length}</span><span class="info-tag">เคลียร์แล้ว ${list.filter(x=>x.status==='เคลียร์แล้ว').length}</span><span class="info-tag">ยกเลิก ${list.filter(x=>x.status==='ยกเลิก').length}</span></div></div></div><div class="section-title" style="margin-top:12px">สรุปตามหมวด</div><div class="table-wrap"><table><thead><tr><th>หมวด</th><th>ยอดรวม</th></tr></thead><tbody>${Object.keys(catMap).length?Object.entries(catMap).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${money2(v)}</td></tr>`).join(''):'<tr><td colspan="2">ไม่มีข้อมูล</td></tr>'}</tbody></table></div><div class="section-title" style="margin-top:12px">รายการในเดือน</div><div class="table-wrap"><table class="wide-table"><thead><tr><th>เลขที่</th><th>วันที่</th><th>ผู้เบิก</th><th>วัตถุประสงค์</th><th>จำนวนเงิน</th><th>สถานะ</th></tr></thead><tbody>${list.length?list.map(x=>`<tr><td>${esc(x.docNo)}</td><td>${fileDateText(x.date)}</td><td>${esc(x.requester||'-')}</td><td>${esc(x.purpose||'-')}</td><td>${money2(x.amount)}</td><td>${esc(x.status||'-')}</td></tr>`).join(''):'<tr><td colspan="6">ไม่มีข้อมูล</td></tr>'}</tbody></table></div><div class="button-row" style="margin-top:12px"><button class="soft-btn" onclick="closeModal()">ปิด</button><button class="primary-btn" onclick="exportPettyCashCSV()">Export CSV</button></div>`,true); modalPanel.classList.add('large'); }

  function sparePartById(id){return sparePartsStock.find(x=>x.id===id)}
  function purchaseOrderById(id){return purchaseOrders.find(x=>x.id===id)}
  function stockState(p){ const qty=Number(p.currentQty)||0,min=Number(p.minQty)||0,max=Number(p.maxQty)||0,ro=Number(p.reorderPoint)||min; if(max&&qty>max) return {key:'high',label:'เกินค่าสูงสุด',class:'stock-high'}; if(qty<=min) return {key:'low',label:'ต่ำกว่าขั้นต่ำ',class:'stock-low'}; if(qty<=ro) return {key:'reorder',label:'ถึงจุดสั่งซื้อ',class:'stock-reorder'}; return {key:'normal',label:'ปกติ',class:'stock-normal'}; }
  function machineNamesForPart(p){ return (p.machineIds||[]).map(id=>machinePrimaryName(machineById(id)||{})||'').filter(Boolean) }
  function poStatusClass(s=''){ return s==='รับเข้าแล้ว'?'po-received':s==='ยกเลิก'?'po-cancel':s==='สั่งซื้อแล้ว'?'po-order':'po-open'; }
  function poTotal(po){ return (Number(po.qty)||0)*(Number(po.unitCost)||0) }
  window.renderSpareParts=function(){ if(typeof sparePartTable==='undefined')return; const q=(spSearch?.value||'').toLowerCase(),sf=spStatusFilter?.value||'all',mf=spMachineFilter?.value||'all'; spMachineFilter.innerHTML='<option value="all">ทุกเครื่อง</option>'+machines.map(m=>`<option value="${esc(String(m.id))}" ${mf===m.id?'selected':''}>${esc(machinePrimaryName(m))}</option>`).join(''); const spFiltered=sparePartsStock.filter(p=>{ const st=stockState(p), bag=[p.partNo,p.name,p.supplier,p.modelTags,...machineNamesForPart(p)].join(' ').toLowerCase(); return (!q||bag.includes(q))&&(sf==='all'||st.key===sf)&&(mf==='all'||(p.machineIds||[]).includes(mf)); }).sort((a,b)=>String(a.partNo).localeCompare(String(b.partNo))); const spInfo=paginateList('spareParts',spFiltered,[q,sf,mf].join('|')); const list=spInfo.list; spKpiAll.textContent=sparePartsStock.length; spKpiLow.textContent=sparePartsStock.filter(p=>stockState(p).key==='low').length; spKpiReorder.textContent=sparePartsStock.filter(p=>stockState(p).key==='reorder').length; spKpiOver.textContent=sparePartsStock.filter(p=>stockState(p).key==='high').length; spKpiPO.textContent=purchaseOrders.filter(p=>!['รับเข้าแล้ว','ยกเลิก'].includes(p.status)).length; sparePartTable.innerHTML=list.length?list.map(p=>{ const st=stockState(p),names=machineNamesForPart(p); return `<tr><td><b>${esc(p.partNo||'-')}</b></td><td>${esc(p.name||'-')}<span class="subtext">${esc(p.unit||'ชิ้น')} · ${esc(p.location||'-')}</span></td><td>${names.length?names.slice(0,3).map(n=>`<span class="info-tag">${esc(n)}</span>`).join(' '):'-'}${p.modelTags?`<span class="subtext">Model: ${esc(p.modelTags)}</span>`:''}</td><td>${esc(p.supplier||'-')}</td><td><b>${Number(p.currentQty)||0}</b></td><td>${Number(p.minQty)||0}</td><td>${Number(p.maxQty)||0}</td><td>${Number(p.reorderPoint)||0}</td><td><span class="stock-status-badge ${st.class}">${st.label}</span></td><td><button class="mini-btn" onclick="openPurchaseOrderModal(${imodeJsArg(p.id)})">สั่งซื้อ</button> <button class="mini-btn" onclick="openSparePartModal(${imodeJsArg(p.id)})">แก้ไข</button></td></tr>`}).join(''):`<tr><td colspan="10"><div class="empty">ยังไม่มีข้อมูลอะไหล่</div></td></tr>`; sparePartCards.innerHTML=list.map(p=>{ const st=stockState(p); return `<div class="mobile-data-card"><div class="card-top"><div><h4>${esc(p.partNo||'-')}</h4><p>${esc(p.name||'-')}</p></div><span class="stock-status-badge ${st.class}">${st.label}</span></div><p><b>คงเหลือ ${Number(p.currentQty)||0}</b> · Min ${Number(p.minQty)||0} · Max ${Number(p.maxQty)||0}</p><p>${esc((machineNamesForPart(p).slice(0,2).join(', ')||p.modelTags||'-'))}</p><div class="card-actions"><button class="soft-btn" onclick="openPurchaseOrderModal(${imodeJsArg(p.id)})">สั่งซื้อ</button><button class="primary-btn" onclick="openSparePartModal(${imodeJsArg(p.id)})">แก้ไข</button></div></div>`}).join(''); purchaseOrderTable.innerHTML=purchaseOrders.length?purchaseOrders.sort((a,b)=>new Date(b.date)-new Date(a.date)).map(po=>{ const part=sparePartById(po.partId)||{}; return `<tr><td><b>${esc(po.poNo)}</b></td><td>${fileDateText(po.date)}</td><td>${esc(part.partNo||'-')} · ${esc(po.partName||part.name||'-')}</td><td>${esc(po.supplier||'-')}</td><td>${Number(po.qty)||0}</td><td>${fileDateText(po.expectedDate)}</td><td><span class="po-status-badge ${poStatusClass(po.status)}">${esc(po.status||'-')}</span></td><td>${money2(poTotal(po))}</td><td><button class="mini-btn" onclick="openPurchaseOrderModal('',${imodeJsArg(po.id)})">แก้ไข</button></td></tr>`}).join(''):`<tr><td colspan="9"><div class="empty">ยังไม่มีใบสั่งซื้ออะไหล่</div></td></tr>`; if(typeof renderListPager==='function')renderListPager('spareParts',spInfo,sparePartsStock.length); }
  window.openSparePartModal=function(id=''){ const old=sparePartById(id)||{}; const selected=new Set(old.machineIds||[]); openModal(old.id?'แก้ไขอะไหล่':'เพิ่มอะไหล่','ระบุอะไหล่ที่ใช้กับแต่ละเครื่อง และกำหนดจำนวนต่ำสุด/สูงสุดเพื่อแจ้งเตือนสั่งซื้อ',`<form id="spForm"><div class="form-grid cols2"><div class="field"><label>Part No. *</label><input id="spPartNo" value="${esc(old.partNo||'')}" required></div><div class="field"><label>ชื่ออะไหล่ *</label><input id="spName" value="${esc(old.name||'')}" required></div><div class="field"><label>Supplier</label><input id="spSupplier" value="${esc(old.supplier||'')}"></div><div class="field"><label>หน่วย</label><input id="spUnit" value="${esc(old.unit||'ชิ้น')}"></div><div class="field"><label>คงเหลือปัจจุบัน</label><input id="spQty" type="number" min="0" step="1" value="${Number(old.currentQty)||0}"></div><div class="field"><label>ต่ำสุด (Min)</label><input id="spMinQty" type="number" min="0" step="1" value="${Number(old.minQty)||0}"></div><div class="field"><label>สูงสุด (Max)</label><input id="spMaxQty" type="number" min="0" step="1" value="${Number(old.maxQty)||0}"></div><div class="field"><label>จุดสั่งซื้อ (Reorder Point)</label><input id="spReorder" type="number" min="0" step="1" value="${Number(old.reorderPoint)||0}"></div><div class="field"><label>Lead Time (วัน)</label><input id="spLeadTime" type="number" min="0" step="1" value="${Number(old.leadTimeDays)||0}"></div><div class="field"><label>Location</label><input id="spLocation" value="${esc(old.location||'คลัง Service')}"></div><div class="field full"><label>ใช้กับ Model / หมายเหตุรุ่น</label><input id="spModelTags" value="${esc(old.modelTags||'')}"></div><div class="field full"><label>ใช้กับเครื่องใดบ้าง</label><div id="spMachineMap" class="machine-check-grid">${machines.slice(0,120).map(m=>`<label class="machine-check-item"><input type="checkbox" value="${esc(String(m.id))}" ${selected.has(m.id)?'checked':''}><div><b>${esc(machinePrimaryName(m)||'')}</b><small>${esc(m.model||'-')} · ${esc(m.serial||'-')}</small></div></label>`).join('')||'<div class="empty">ยังไม่มีข้อมูลเครื่อง</div>'}</div></div><div class="field full"><label>หมายเหตุ</label><textarea id="spNote">${esc(old.note||'')}</textarea></div></div><div class="button-row"><button type="button" class="soft-btn" onclick="closeModal()">ยกเลิก</button><button class="primary-btn action-3d-orange">💾 บันทึกอะไหล่</button></div></form>`,true); modalPanel.classList.add('large'); setTimeout(()=>spForm.onsubmit=e=>{e.preventDefault(); saveSparePart(id)},20); }
  window.saveSparePart=function(id=''){ const old=sparePartById(id)||{}; const machineIds=[...document.querySelectorAll('#spMachineMap input[type="checkbox"]:checked')].map(x=>x.value); const obj={id:old.id||uid(),partNo:spPartNo.value.trim(),name:spName.value.trim(),supplier:spSupplier.value.trim(),unit:spUnit.value.trim()||'ชิ้น',currentQty:Number(spQty.value)||0,minQty:Number(spMinQty.value)||0,maxQty:Number(spMaxQty.value)||0,reorderPoint:Number(spReorder.value)||0,leadTimeDays:Number(spLeadTime.value)||0,location:spLocation.value.trim(),modelTags:spModelTags.value.trim(),machineIds,note:spNote.value.trim(),createdAt:old.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()}; if(!obj.partNo||!obj.name){toastMsg('กรุณากรอก Part No. และชื่ออะไหล่');return} if(!obj.reorderPoint)obj.reorderPoint=obj.minQty; if(old.id) sparePartsStock=sparePartsStock.map(x=>x.id===obj.id?obj:x); else sparePartsStock.unshift(obj); saveLocal(); closeModal(); renderAll(); toastMsg('บันทึกอะไหล่แล้ว'); }
  function poNo(){ const ym=currentMonthValue().replace('-',''); let max=0; purchaseOrders.forEach(x=>{const m=String(x.poNo||'').match(/PO-\d{6}-(\d+)/); if(m)max=Math.max(max,Number(m[1])||0)}); return `PO-${ym}-${String(max+1).padStart(3,'0')}`; }
  window.openPurchaseOrderModal=function(partId='',poId=''){ const old=poId?purchaseOrderById(poId)||{}:{}; const preset=sparePartById(partId)||sparePartById(old.partId)||{}; openModal(old.id?'แก้ไขใบสั่งซื้อ':'สร้างใบสั่งซื้ออะไหล่','ติดตามการสั่งซื้อและแจ้งเตือนอะไหล่ที่ต้องเติมสต๊อก',`<form id="poForm"><div class="form-grid cols2"><div class="field"><label>PO No.</label><input id="poNoInput" value="${esc(old.poNo||poNo())}" readonly></div><div class="field"><label>วันที่</label><input id="poDate" type="date" value="${esc(old.date||todayISO())}"></div><div class="field"><label>อะไหล่ *</label><select id="poPartId">${sparePartsStock.map(p=>`<option value="${esc(String(p.id))}" ${((old.partId||preset.id)===p.id)?'selected':''}>${esc(p.partNo)} · ${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Supplier</label><input id="poSupplier" value="${esc(old.supplier||preset.supplier||'')}"></div><div class="field"><label>จำนวน *</label><input id="poQty" type="number" min="1" step="1" value="${Number(old.qty)||1}" required></div><div class="field"><label>ราคาต่อหน่วย</label><input id="poUnitCost" type="number" min="0" step="0.01" value="${Number(old.unitCost)||0}"></div><div class="field"><label>กำหนดรับเข้า</label><input id="poExpectedDate" type="date" value="${esc(old.expectedDate||'')}"></div><div class="field"><label>สถานะ</label><select id="poStatus"><option ${old.status==='รออนุมัติ' || !old.status ? 'selected' : ''}>รออนุมัติ</option><option ${old.status==='สั่งซื้อแล้ว'?'selected':''}>สั่งซื้อแล้ว</option><option ${old.status==='รับเข้าแล้ว'?'selected':''}>รับเข้าแล้ว</option><option ${old.status==='ยกเลิก'?'selected':''}>ยกเลิก</option></select></div><div class="field full"><label>หมายเหตุ</label><textarea id="poNote">${esc(old.note||'')}</textarea></div></div><div class="button-row"><button type="button" class="soft-btn" onclick="closeModal()">ยกเลิก</button><button class="primary-btn action-3d-orange">💾 บันทึกใบสั่งซื้อ</button></div></form>`,true); setTimeout(()=>poForm.onsubmit=e=>{e.preventDefault(); savePurchaseOrder(poId)},20); }
  window.savePurchaseOrder=function(poId=''){ const old=poId?purchaseOrderById(poId)||{}:{}; const part=sparePartById(poPartId.value)||{}; const obj={id:old.id||uid(),poNo:poNoInput.value,date:poDate.value,partId:poPartId.value,partName:part.name||'',supplier:poSupplier.value.trim(),qty:Number(poQty.value)||0,unitCost:Number(poUnitCost.value)||0,expectedDate:poExpectedDate.value,status:poStatus.value,note:poNote.value.trim(),createdAt:old.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()}; if(!obj.partId||!obj.qty){toastMsg('กรุณาเลือกอะไหล่และจำนวน');return} if(old.id) purchaseOrders=purchaseOrders.map(x=>x.id===obj.id?obj:x); else purchaseOrders.unshift(obj); /* 2026-09-19 — RECEIVING STOCK IS A TRANSITION, NOT A STATE.
    This used to add obj.qty to the part whenever the status READ 'รับเข้าแล้ว', with no
    look at what the PO said before. So re-opening an already-received PO and pressing
    บันทึก again — to fix a supplier name, a unit cost, a note — added the whole quantity
    to stock a second time, and a third, compounding every save. Measured: a part at 2,
    one PO of 5 received, then two no-op saves and a 5->8 correction, ended at 25 instead
    of 10.
    The delta is now taken from the transition between the OLD row and the new one, which
    is idempotent and also handles the two cases the old code could not: correcting the
    quantity of a PO that is already received (apply only the difference), and taking a
    received PO back to สั่งซื้อแล้ว / ยกเลิก (give the stock back). */
 if(obj.partId){
  const wasIn=old.status==='รับเข้าแล้ว', isIn=obj.status==='รับเข้าแล้ว';
  const oldQty=Number(old.qty)||0, newQty=Number(obj.qty)||0;
  const delta=(!wasIn&&isIn)?newQty:(wasIn&&!isIn)?-oldQty:(wasIn&&isIn)?(newQty-oldQty):0;
  if(delta) sparePartsStock=sparePartsStock.map(p=>p.id===obj.partId?{...p,currentQty:(Number(p.currentQty)||0)+delta,updatedAt:new Date().toISOString()}:p);
 } saveLocal(); closeModal(); renderAll(); toastMsg('บันทึกใบสั่งซื้อแล้ว'); }
  window.exportSparePartsCSV=function(){ if(!sparePartsStock.length){toastMsg('ยังไม่มีข้อมูลอะไหล่');return} const rows=[['Part No','Name','Supplier','Qty','Min','Max','Reorder Point','Status','Location','Machines','Model Tags'],...sparePartsStock.map(p=>[p.partNo,p.name,p.supplier||'',p.currentQty||0,p.minQty||0,p.maxQty||0,p.reorderPoint||0,stockState(p).label,p.location||'',machineNamesForPart(p).join(' | '),p.modelTags||''])]; const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n'); downloadTextFile(`I-MODE_Spare_Parts_${todayISO()}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8'); }

  function buildSystemBackup(){ return {format:'I-MODE-SERVICE-BACKUP',version:'6.8',exportedAt:new Date().toISOString(),data:{customers,machines,cases,technicians,quotations,warranties,machineDocuments,lineRequests,serviceReports,qcRecords,pettyCashEntries,sparePartsStock,purchaseOrders,notifications,settings,currentUser}} }
  window.buildSystemBackup=buildSystemBackup;
  window.exportSystemBackup=function(){ const b=buildSystemBackup(); downloadTextFile(`I-MODE_Service_Backup_${new Date().toISOString().replace(/[:.]/g,'-').slice(0,19)}.json`,JSON.stringify(b,null,2),'application/json'); }
  window.importSystemBackup=function(input){ const file=input.files?.[0]; if(!file)return; const r=new FileReader(); r.onload=()=>{ try{ const b=JSON.parse(r.result),d=b.data||b; if(!Array.isArray(d.customers)||!Array.isArray(d.machines))throw new Error('backup invalid'); if(!confirm('นำ Backup นี้เข้าระบบและแทนที่ข้อมูลปัจจุบันหรือไม่?'))return; customers=d.customers||[]; machines=d.machines||[]; cases=d.cases||[]; technicians=d.technicians||technicians; quotations=d.quotations||[]; warranties=d.warranties||[]; machineDocuments=d.machineDocuments||[]; lineRequests=d.lineRequests||[]; serviceReports=d.serviceReports||[]; qcRecords=d.qcRecords||[]; pettyCashEntries=d.pettyCashEntries||[]; sparePartsStock=d.sparePartsStock||[]; purchaseOrders=d.purchaseOrders||[]; notifications=d.notifications||[]; settings=mergeSettings(d.settings||settings); currentUser=d.currentUser||currentUser; ensureInternalCustomer(); saveLocal(); closeModal(); renderAll(); toastMsg('Restore Backup เรียบร้อย'); }catch(e){toastMsg('ไฟล์ Backup ไม่ถูกต้อง')}}; r.readAsText(file); input.value=''; }
  window.clearTestDataWithBackup=function(){ if(!confirm('แนะนำให้ Export Backup ก่อน คุณต้องการล้างข้อมูลธุรกรรมทดสอบหรือไม่?'))return; cases=[]; quotations=[]; lineRequests=[]; serviceReports=[]; qcRecords=[]; pettyCashEntries=[]; purchaseOrders=[]; notifications=[]; saveLocal(); closeModal(); renderAll(); toastMsg('ล้างข้อมูลธุรกรรมทดสอบแล้ว'); }
  window.openDataBackupModal=function(){ const b=buildSystemBackup(),d=b.data; openModal('Data Backup / Restore','ข้อมูลระบบแยกสำรองเป็น JSON สามารถเปิดแก้ไขและนำกลับมาใช้งานได้',`<div class="backup-grid"><div class="backup-card"><h4>💾 Export Backup</h4><p>รวม Customer, Machine, Service Case, Quotation, Warranty, Documents, Service Report, QC, เงินสดย่อย, สต๊อกอะไหล่ และใบสั่งซื้อ</p><button class="primary-btn action-3d-orange" onclick="exportSystemBackup()">ดาวน์โหลด Backup JSON</button><div class="backup-data-list"><span>Customers ${d.customers.length}</span><span>Machines ${d.machines.length}</span><span>Cases ${d.cases.length}</span><span>QC ${d.qcRecords.length}</span><span>Petty Cash ${d.pettyCashEntries.length}</span><span>Parts ${d.sparePartsStock.length}</span></div></div><div class="backup-card"><h4>↥ Import / Restore</h4><p>เลือกไฟล์ Backup JSON ที่เคย Export หรือไฟล์ Data ที่แก้ไขแล้ว ระบบจะนำข้อมูลกลับมาใช้งาน</p><label class="soft-btn" style="cursor:pointer;display:inline-flex">เลือกไฟล์ Backup<input type="file" accept=".json,application/json" style="display:none" onchange="importSystemBackup(this)"></label><div class="backup-warning">ก่อน Restore ควร Export Backup ของข้อมูลปัจจุบันเก็บไว้อีก 1 ชุด</div></div></div><div class="backup-card" style="margin-top:12px"><h4>🧹 Reset สำหรับ Test</h4><p>ล้างเฉพาะข้อมูลธุรกรรม เช่น Cases / Quotations / Reports / QC / เงินสดย่อย / ใบสั่งซื้อ โดยยังเก็บ Customer, Machine, Warranty และรายการอะไหล่หลัก</p><button class="soft-btn" onclick="clearTestDataWithBackup()">ล้างข้อมูลธุรกรรมทดสอบ</button></div>`,true); modalPanel.classList.add('large'); }
  window.renderAll=function(){ applyFontScale(); ensureMasters(); applyOfficialImodeLogo(); renderDashboard(); renderCases(); renderCustomers(); renderMachines(); renderQc(); renderPettyCash(); renderSpareParts(); renderTechnicians(); renderCalendar(); renderNotifications(); renderReports(); renderSettings(); renderQuotations(); renderWarranties(); renderMachineDocuments(); renderLineRequests(); renderFieldService(); renderServiceReports(); renderUserCard(); applyRoleVisibility(); };
  (function seedV67Data(){ ensureInternalCustomer(); if(((window.IMODE_ENV&&window.IMODE_ENV.production)||window.IMODE_NO_DEMO))return; /* production: no demo petty cash / parts / POs */ if(!pettyCashEntries.length){ pettyCashEntries=[{id:'PC-DEMO-001',docNo:'PC-202608-001',date:'2026-08-30',requester:'ผู้จัดการ ตัวอย่าง',category:'อะไหล่',purpose:'ซื้อฟิวส์สำรองและคอนเนคเตอร์ใช้ในงาน Service',vendor:'ร้านช่างไฟบางนา',amount:1250,status:'รอเคลียร์',reference:'REC-001',note:'TEST DATA',receipts:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},{id:'PC-DEMO-002',docNo:'PC-202608-002',date:'2026-08-29',requester:'สมชาย ใจดี',category:'วัสดุสิ้นเปลือง',purpose:'ซื้อ IPA และผ้าเช็ดทำความสะอาด',vendor:'Makro',amount:860,status:'เคลียร์แล้ว',reference:'REC-002',note:'TEST DATA',receipts:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}]; } if(!sparePartsStock.length){ const sampleMachines=machines.slice(0,4).map(m=>m.id); sparePartsStock=[{id:'SP-DEMO-001',partNo:'SP-HO500WT-FUSE',name:'Fuse 5A 250V',supplier:'Thai Electric',unit:'ชิ้น',currentQty:2,minQty:3,maxQty:12,reorderPoint:4,leadTimeDays:3,location:'ชั้น A1',modelTags:'HO500WT',machineIds:sampleMachines.slice(0,2),note:'อะไหล่ไฟฟ้าหลัก',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},{id:'SP-DEMO-002',partNo:'SP-LASER-BELT',name:'Timing Belt',supplier:'Motion Plus',unit:'เส้น',currentQty:6,minQty:2,maxQty:10,reorderPoint:3,leadTimeDays:7,location:'ชั้น B2',modelTags:'Laser Marking',machineIds:sampleMachines.slice(1,3),note:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},{id:'SP-DEMO-003',partNo:'SP-PUMP-COOL',name:'Cooling Pump',supplier:'Coolflow',unit:'ตัว',currentQty:11,minQty:2,maxQty:8,reorderPoint:3,leadTimeDays:10,location:'ชั้น C1',modelTags:'Universal',machineIds:sampleMachines.slice(0,1),note:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}]; } if(!purchaseOrders.length){ purchaseOrders=[{id:'PO-DEMO-001',poNo:'PO-202608-001',date:'2026-08-31',partId:'SP-DEMO-001',partName:'Fuse 5A 250V',supplier:'Thai Electric',qty:10,unitCost:28,expectedDate:'2026-09-03',status:'สั่งซื้อแล้ว',note:'TEST DATA',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}]; } saveLocal(); })();

  /* js/41 syncs these three arrays to the cloud, and they are `let` inside this IIFE — not
     even lexical globals, so nothing outside can reach them. Two accessors rather than
     making them global: the arrays stay owned here, and a download can replace them in
     place instead of needing a page reload for the office to see what the tablet added. */
  window.imodeV67Data={
    get:function(){return {pettyCash:pettyCashEntries,spareParts:sparePartsStock,purchaseOrders:purchaseOrders}},
    set:function(d){
      if(d&&Array.isArray(d.pettyCash))pettyCashEntries=d.pettyCash;
      if(d&&Array.isArray(d.spareParts))sparePartsStock=d.spareParts;
      if(d&&Array.isArray(d.purchaseOrders))purchaseOrders=d.purchaseOrders;
    }
  };
})();
